-- Jetons d'ensemble (anciens raids) : la conversion donnait « Debris bruts » (128630) a toutes les classes.
-- Base : dc_world. Rejouable. Signalement du 17/10/2026 (le baltring) : « tous les tokens du jeu donnent
-- Debris bruts au lieu des items de ma classe » (Gruul, Karazhan ; idem chasseur et chevalier de la mort).
--
-- Un jeton se convertit par un sort a effet 157 sans objet fixe : Spell::EffectCreateItem2 appelle
-- AutoStoreLoot(sort, spell_loot_template, specOnly = true) : seuls les objets utilisables par la
-- specialisation de butin du joueur sont donnes. Chez nous ces sorts n'avaient qu'UNE ligne, l'objet de
-- remplissage 128630. Contenu repris de LegionCore pour les 312 sorts dont la table ne contenait QUE cette
-- ligne et dont tout le contenu LegionCore est de l'equipement (le filtre de specialisation ne trie que
-- l'equipement). Chance 0 chez LegionCore (et 100) -> 100 : chez nous une ligne hors groupe a chance 0
-- ne tombe jamais, et un groupe ignore le filtre de specialisation (Loot.cpp / LootMgr.cpp).
-- Non traites (laisses tels quels) : 46 sorts au contenu LegionCore non equipement, et ~127 sorts sans
-- contenu LegionCore.

